TLM.f("Sancti/09-14",{"officium":"In Exaltatione Sanctæ Crucis","rule":["ex Sancti/05-03","Gloria","Credo","Prefatio=Quad5"],"ruleInherited":["Gloria","Credo","Prefatio=Quad5"],"fallback":"Sancti/05-03","sections":{"Introitus":[{"k":"ref","la":"Gal 6:14"},{"k":"text","la":"Nos autem gloriári opórtet in Cruce Dómini nostri Jesu Christi: in quo est salus, vita et resurréctio nostra: per quem salváti et liberáti sumus."},{"k":"ref","la":"Ps 66:2"},{"k":"text","la":"Deus misereátur nostri, et benedícat nobis: illúminet vultum suum super nos, et misereátur nostri."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Nos autem gloriári opórtet in Cruce Dómini nostri Jesu Christi: in quo est salus, vita et resurréctio nostra: per quem salváti et liberáti sumus."}],"Oratio":[{"k":"text","la":"Deus, qui nos hodiérna die Exaltatiónis sanctæ Crucis ánnua sollemnitáte lætíficas: præsta, quǽsumus; ut, cujus mystérium in terra cognóvimus, ejus redemptiónis præmia in cœlo mereámur."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Philipp 2:5-11"},{"k":"text","la":"Fratres: Hoc enim sentíte in vobis, quod et in Christo Jesu: qui, cum in forma Dei esset, non rapinam arbitrátus est esse se æquálem Deo: sed semetípsum exinanívit, formam servi accipiens, in similitudinem hóminum factus, et hábitu inventus ut homo. Humiliávit semetípsum, factus obœ́diens usque ad mortem, mortem autem crucis. Propter quod et Deus exaltávit illum: et donávit illi nomen, quod est super omne nomen: (hic genuflectitur) ut in nomine Jesu omne genu flectátur cœléstium, terréstrium et infernórum: et omnis lingua confiteátur, quia Dóminus Jesus Christus in glória est Dei Patris."}],"Graduale":[{"k":"ref","la":"Phil 2:8-9"},{"k":"text","la":"Christus factus est pro nobis obœ́diens usque ad mortem, mortem autem crucis."},{"k":"text","la":"Propter quod et Deus exaltávit illum, et dedit illi nomen, quod est super omne nomen. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Dulce lignum, dulces clavos, dúlcia ferens póndera: quæ sola fuísti digna sustinére Regem cœlórum et Dóminum. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 12:31-36"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis Judæórum: Nunc judícium est mundi: nunc princeps hujus mundi ejiciétur foras. Et ego si exaltátus fuero a terra, ómnia traham ad meipsum. ((Hoc autem dicébat, signíficans qua morte esset moritúrus.)) Respóndit ei turba. Nos audívimus ex lege, quia Christus manet in ætérnum: et quómodo tu dicis: Opórtet exaltári Fílium hóminis? Quis est iste Fílius hóminis? Dixit ergo eis Jesus: Adhuc módicum lumen in vobis est. Ambuláte, dum lucem habétis, ut non vos ténebræ comprehéndant: et qui ámbulat in ténebris, nescit, quo vadat. Dum lucem habétis, crédite in lucem, ut fílii lucis sitis."}],"Offertorium":[{"k":"text","la":"Prótege, Dómine, plebem tuam per signum sanctæ Crucis ab ómnibus insídiis inimicórum ómnium: ut tibi gratam exhibeámus servitútem, et acceptábile fiat sacrifícium nostrum, allelúja."}],"Secreta":[{"k":"text","la":"Jesu Christi, Dómini nostri, Córpore et Sánguine saginándi, per quem Crucis est sanctificátum vexíllum: quǽsumus, Dómine, Deus noster; ut, sicut illud adoráre merúimus, ita perénniter ejus glóriæ salutáris potiámur efféctu."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"text","la":"Per signum Crucis de inimícis nostris líbera nos, Deus noster."}],"Postcommunio":[{"k":"text","la":"Adésto nobis, Dómine, Deus noster: et, quos sanctæ Crucis lætári facis honóre, ejus quoque perpétuis defénde subsídiis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"22d0eb1edc277857":{"t":"Gal 6, 14, Ps 66, 2\n(Gal 6, 14) Mi treba da se dičimo križem Gospodina našega Isusa Krista. U njemu je naše spasenje, život i uskrsnuće. Po njemu smo spašeni i izbavljeni. (Ps 66, 2) Nek nam se smiluje Bog i neka nas blagoslovi! Neka naš obasja svojim licem i nek nam se smiluje! (Gal 6, 14) Mi treba da se dičimo križem Gospodina našega Isusa Krista. U njemu je naše spasenje, život i uskrsnuće. Po njemu smo spašeni i izbavljeni. [u vremenu Muke ne govori se Slava Ocu u sklopu Ulazne pjesme]"},"f143c3478c1b1f10":{"t":"<i>Pomolimo se</i>.\nBože, koji nas na današnji dan razveseljuješ godišnjom svetkovinom uzvišenja svetoga Križa, podaj molimo, da u nebu zadobijemo nagradu otkupljenja onoga, kojega smo otajstvo upoznali na zemlji.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c8fc6346ccfc9ea2":{"t":"Fil 2, 5-11\nČitanje Poslanice bl. Pavla apostola Filipljanima. Braćo: imajte u sebi ono isto mišljenje koje je u Kristu Isusu. Budući da je imao narav Božju, nije držao za otimačinu, da bude jednak Bogu. Ali je sebe poništio uzevši narav sluge, postao je sličan ljudima i vladao se kao čovjek. Ponizio je sam sebe postavši poslušan sve do smrti, i to do smrti na križu. A zato Bog njega uzvisi i darova mu ime koje je nad svakim imenom, [ovdje se poklekne] da se u ime Isusovo pokloni svako koljeno onih koji su na nebu, na zemlji i pod zemljom. I svaki jezik da prizna, da je Gospodin Isus Krist u slavi Boga Oca."},"a735d715045b6f2b":{"t":"Fil 2, 8-9\nKrist je postao za nas poslušan sve do smrti i to do smrti na križu. Zato Bog njega uzvisi i darova mu ime, koje je nad svakim imenom.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nSlatko drvo, slatki čavli nose teret slatki taj Samo ti si bilo dostojno nositi nebeskoga Kralja i Gospodina. <i>Aleluja</i>."},"b49f1a4aa15ebeed":{"t":"Iv 12, 31-36\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus židovskom narodu: Sada je sud svijetu, sad će knez ovoga svijeta biti bačen van. A ja, kad budem podignut sa zemlje, sve ću privući k sebi. Ovo reče, da najavi kakvom će smrću umrijeti. Narod mu odgovori: Čuli smo u zakonu, da Krist ostaje zauvijek. Kako ti kažeš, da Sin čovječji treba da bude podignut? Tko je taj Sin čovječji? Isus im odgovori: Još je malo vremena svjetlo među vama. Hodajte dok imate svjetlo, da vaš ne bi osvojila tama! Tko hoda u tami, ne zna kamo ide. Dok imate svjetlo, vjerujte u svjetlo, da postanete sinovi svjetla!"},"3685e1aacd8bad5e":{"t":"Štiti, Gospodine, znakom svetoga Križa puk svoj od zasjeda svih neprijatelja, da ti ugodno služimo i da ti bude prijatna naša žrtva, <i>aleluja</i>."},"0a7c75d368699b49":{"t":"Prije nego se nahranimo Tijelom i Krvlju Isusa Krista Gospodina našega po kojem je posvećen stijeg Križa, molimo, Gospodine Bože naš, da kao što smo zavrijedili častiti Križ, tako da zauvijek primimo djelo njegove spasonosne slave.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f2fb1fe68f386b18":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti si odredio spasenje ljudskog roda po drvu Križa, da se opet rodi život ondje gdje je nikla smrt, i onaj koji je na drvu pobijedio, bude pobijeđen na drvu po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glas primi dok govorimo poniznim hvalospjevom:"},"d420e82f3fa1ea24":{"t":"Znakom križa oslobodi naš od neprijatelja naših, Bože naš!"},"de004fda4123d264":{"t":"<i>Pomolimo se</i>.\nPomozi nam, Gospodine Bože naš, i one koje razveseljuješ čašću svetoga Križa, daj i brani njegovom neprestanom pomoću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
